package com.huawei.finance.domain.deposit;
import static org.assertj.core.api.Assertions.assertThat;
import com.huawei.finance.contracts.model.Enums; import com.huawei.finance.contracts.model.GuardrailCheck; import com.huawei.finance.contracts.model.RiskLevel; import com.huawei.finance.contracts.model.UnifiedTask; import java.time.Instant; import java.util.List; import java.util.Map; import org.junit.jupiter.api.Test;
class DepositDomainAgentTest { @Test void returnsOnlyPortFacts(){var agent=new DepositDomainAgent(()->new DepositCatalogPort.ProductView("D","定期","存款","R0","2%","1年"));var result=agent.execute(task("cap.deposit.product.query",Map.of()));assertThat(result.status()).isEqualTo(Enums.TaskStatus.SUCCESS);assertThat(result.resultPayload()).containsEntry("productCode","D");} private static UnifiedTask task(String cap,Map<String,Object> p){return new UnifiedTask("t","trace",Enums.TaskSource.FAST_PATH,"查询",cap,p,RiskLevel.R0,Map.of(),GuardrailCheck.passed(),"idem",List.of(),Instant.now().plusSeconds(5));}}
